// === COMPUTE FINAL SCORES ===
// Przelicza LLM output (level, impactBonus:bool, bountyApplied:bool)
// na format wymagany przez OM Import API:
//   wicScore:number, impactBonus:number, bountyBonus:number
//
// Formula z app-spec Macieja:
//   base_score = { L4:1.0, L3:0.5, L2:1.0, L1:0.25, routine:0.0 }
//   impact_bonus = +0.25 (scope: >=40 files) + 0.25 (completeness: testy)
//   wic_pre_bounty = base_score + impact_bonus
//   bountyBonus = wic_pre_bounty * 0.5 (jesli bounty applied)
//   wicScore = wic_pre_bounty + bountyBonus

const BASE_SCORES = { L4: 1.0, L3: 0.5, L2: 1.0, L1: 0.25, routine: 0.0 };

const items = $input.all();
const originals = $('Expand Contribution Candidates1').all();

return items.map((item, index) => {
  const r = item.json;
  const orig = originals[index]?.json ?? {};

  // 1. Base score z poziomu
  const baseScore = BASE_SCORES[r.level] ?? 0;

  // 2. Impact bonus — przelicz z boolean na number
  let impactBonus = 0;
  if (r.impactBonus === true) {
    const scopeBonus = (orig.uniqueFilesCount ?? 0) >= 40 ? 0.25 : 0;
    const hasTests = (orig.files ?? []).some(f =>
      /\.test\.|\.spec\.|__tests__|__integration__/.test(f)
    );
    const completenessBonus = hasTests ? 0.25 : 0;
    impactBonus = scopeBonus + completenessBonus;
    // LLM powiedzial true — minimum 0.25
    if (impactBonus === 0) impactBonus = 0.25;
  }

  // 3. Bounty bonus
  const wicPreBounty = baseScore + impactBonus;
  const bountyBonus = r.bountyApplied === true
    ? Math.round(wicPreBounty * 0.5 * 100) / 100
    : 0;

  // 4. Final WIC score
  const wicScore = Math.round((wicPreBounty + bountyBonus) * 100) / 100;

  // 5. Included / excluded
  const prIds = orig.prIds ?? [r.prId];
  const included = prIds.map(id => `#${id}`).join(', ') +
    (orig.titlesStr ? ` — ${orig.titlesStr}` : '');

  // 6. Why bonus
  const whyParts = [];
  if (impactBonus > 0) {
    if ((orig.uniqueFilesCount ?? 0) >= 40) whyParts.push(`scope: ${orig.uniqueFilesCount} files`);
    if ((orig.files ?? []).some(f => /\.test\.|\.spec\.|__tests__|__integration__/.test(f))) {
      whyParts.push('completeness: tests present');
    }
  }
  if (r.bountyApplied) whyParts.push('bounty: 1.5x multiplier');

  return {
    json: {
      contributorGithubUsername: r.contributorGithubUsername,
      month: r.month,
      wicScore,
      level: r.level,
      impactBonus: Math.round(impactBonus * 100) / 100,
      bountyBonus,
      whyBonus: whyParts.join('; '),
      included: included.slice(0, 2000),
      excluded: '',
      scriptVersion: 'n8n-wic-v1.0',
      _rationale: r.rationale || ''
    }
  };
});

// === BUILD WIC IMPORT BATCH ===
// Grupuje assessments per organizacja.
// OM API wymaga jednego POST per org+month.
//
// KONFIGURACJA: Mapowanie GitHub username -> organizationId (UUID z OM).
// Uzupelnij prawdziwe UUID po sprawdzeniu w OM.
const ORG_MAP = {
  'pkarw': 'UZUPELNIJ-UUID-ORGANIZACJI-PKARW',
  'matgren': 'UZUPELNIJ-UUID-ORGANIZACJI-MATGREN'
};

const all = $input.all().map(item => item.json);
const month = all[0]?.month ?? new Date().toISOString().slice(0, 7);

// Grupuj per org
const byOrg = new Map();
const unmapped = [];

for (const a of all) {
  const orgId = ORG_MAP[a.contributorGithubUsername];
  if (!orgId || orgId.startsWith('UZUPELNIJ')) {
    unmapped.push(a.contributorGithubUsername);
    continue;
  }
  if (!byOrg.has(orgId)) byOrg.set(orgId, []);
  byOrg.get(orgId).push({
    contributorGithubUsername: a.contributorGithubUsername,
    month: a.month,
    wicScore: a.wicScore,
    level: a.level,
    impactBonus: a.impactBonus,
    bountyBonus: a.bountyBonus,
    whyBonus: a.whyBonus || '',
    included: a.included || '',
    excluded: a.excluded || '',
    scriptVersion: a.scriptVersion || 'n8n-wic-v1.0'
  });
}

if (unmapped.length > 0) {
  throw new Error(
    'Brak organizationId w ORG_MAP dla: ' +
    [...new Set(unmapped)].join(', ') +
    '. Uzupelnij ORG_MAP w nodzie Build WIC Import Batch.'
  );
}

// Jeden item per org = jeden POST
return Array.from(byOrg.entries()).map(([orgId, records]) => ({
  json: {
    organizationId: orgId,
    month,
    source: 'automated_pipeline',
    records
  }
}));

// === CONFIGURATION ===
// Dodaj GitHub loginy kontrybutorów do oceny.
// Kazdy profil dostanie osobne query do GitHuba (petla).
// When OM API is ready, replace with fetch from /api/contributors.
const PROFILES = ['pkarw', 'matgren'];
const REPO = 'open-mercato/open-mercato';
// === END CONFIGURATION ===

const now = new Date();
const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1, 0, 0, 0, 0));
const fromIso = monthStart.toISOString();

return [{
  json: {
    repoFullName: REPO,
    profiles: PROFILES,
    month: now.toISOString().slice(0, 7),
    fromIso,
    toIso: now.toISOString(),
    generatedAt: now.toISOString(),
    bountySearchQuery: `repo:${REPO} is:issue label:bounty`
  }
}];

// Rozbija PROFILES na osobne itemy — kazdy profil leci osobno przez GitHub query.
// Zeby dodac wiecej osob, edytuj PROFILES w Set Period Context.
const ctx = $input.first().json;
return ctx.profiles.map(profile => ({
  json: {
    ...ctx,
    currentProfile: profile,
    prSearchQuery: `repo:${ctx.repoFullName} is:pr is:merged merged:>=${ctx.fromIso} author:${profile}`,
    unmergedPrSearchQuery: `repo:${ctx.repoFullName} is:pr -is:merged updated:>=${ctx.fromIso} author:${profile}`,
    issuesSearchQuery: `repo:${ctx.repoFullName} is:issue -label:bounty created:>=${ctx.fromIso} author:${profile}`
  }
}));

