// Iteruje po WSZYSTKICH profilach — .all() + index
const allProfiles = $('Split Profiles1').all();
const allPr = $('GitHub PR Search1').all();
const allUnmerged = $('GitHub Unmerged PR Search1').all();
const allIssues = $('GitHub Issues Search1').all();
const allBounty = $('GitHub Bounty Search1').all();

// Zbierz errors ze wszystkich profili
const errors = [];
for (let i = 0; i < allProfiles.length; i++) {
  for (const resp of [allPr[i]?.json, allUnmerged[i]?.json, allIssues[i]?.json, allBounty[i]?.json]) {
    if (resp?.errors) errors.push(...resp.errors);
  }
}
if (errors.length > 0) {
  throw new Error('GitHub GraphQL returned errors: ' + JSON.stringify(errors.slice(0, 3)));
}

// Polacz dane ze wszystkich profili
let allMergedPrs = [];
let allUnmergedPrs = [];
let allBountyIssues = [];
let allAuthoredIssues = [];

for (let i = 0; i < allProfiles.length; i++) {
  allMergedPrs.push(...(allPr[i]?.json?.data?.search?.nodes ?? []).filter(Boolean));
  allUnmergedPrs.push(...(allUnmerged[i]?.json?.data?.search?.nodes ?? []).filter(Boolean));
  allBountyIssues.push(...(allBounty[i]?.json?.data?.search?.nodes ?? []).filter(Boolean));
  allAuthoredIssues.push(...(allIssues[i]?.json?.data?.search?.nodes ?? []).filter(Boolean));
}

// Deduplikuj bounty po numerze
const bountyMap = new Map();
allBountyIssues.forEach(b => bountyMap.set(b.number, b));
allBountyIssues = Array.from(bountyMap.values());

const period = allProfiles[0].json;
const mergedPrs = allMergedPrs;
const unmergedPrs = allUnmergedPrs;
const bountyIssues = allBountyIssues;
const authoredIssues = allAuthoredIssues;
const fromDate = new Date(period.fromIso);

const bountyByNumber = new Map();
for (const issue of bountyIssues) {
  const issueDate = issue.closedAt ? new Date(issue.closedAt) : new Date(issue.createdAt || 0);
  if (issue.state === 'OPEN' || issueDate >= fromDate) {
    bountyByNumber.set(String(issue.number), {
      number: String(issue.number),
      title: issue.title || '',
      body: issue.body || '',
      state: issue.state || 'OPEN',
      labels: (issue.labels?.nodes ?? []).map(label => label.name),
      url: issue.url || ''
    });
  }
}

function uniqueStrings(values) {
  return Array.from(new Set(values.filter(Boolean).map(value => String(value))));
}

function extractIssueNumbers(text) {
  if (!text || typeof text !== 'string') return [];
  const matches = text.match(/#(\d+)/g) ?? [];
  return uniqueStrings(matches.map(match => match.replace('#', '')));
}

function hasApprovedReview(pr) {
  return (pr.reviews?.nodes ?? []).some(r => r.state === 'APPROVED');
}

function normalizePr(pr, isUnmergedApproved) {
  const files = (pr.files?.nodes ?? []).map(f => f.path).filter(Boolean);
  const labels = (pr.labels?.nodes ?? []).map(l => l.name).filter(Boolean);
  const reviews = (pr.reviews?.nodes ?? []).map(r => `${r.author?.login || 'unknown'}: ${r.state}`);
  const linkedIssues = (pr.closingIssuesReferences?.nodes ?? []).map(issue => ({
    number: String(issue.number),
    title: issue.title || '',
    body: issue.body || '',
    url: issue.url || '',
    labels: (issue.labels?.nodes ?? []).map(l => l.name).filter(Boolean)
  }));
  const referencedIssueNumbers = uniqueStrings([
    ...linkedIssues.map(i => i.number),
    ...extractIssueNumbers(pr.title || ''),
    ...extractIssueNumbers(pr.body || '')
  ]);
  const bountyCandidates = referencedIssueNumbers
    .map(n => bountyByNumber.get(n))
    .filter(Boolean);

  return {
    recordType: 'pull_request',
    isUnmergedApproved,
    contributorGithubUsername: pr.author?.login ?? 'unknown',
    prId: String(pr.number),
    title: pr.title || '',
    body: (pr.body || '').slice(0, 2000),
    month: period.month,
    mergedAt: pr.mergedAt || null,
    createdAt: null,
    additions: pr.additions ?? 0,
    deletions: pr.deletions ?? 0,
    changedFiles: pr.changedFiles ?? 0,
    files,
    filesStr: files.slice(0, 30).join(', '),
    labels,
    labelsStr: labels.join(', '),
    reviews,
    reviewsStr: reviews.join('; '),
    linkedIssues,
    linkedIssuesStr: linkedIssues.map(i => `#${i.number} ${i.title}`).join('; '),
    referencedIssueNumbers,
    bountyCandidates,
    bountyContextStr: bountyCandidates.map(i => `#${i.number} ${i.title}`).join('; ')
  };
}

const mergedRecords = mergedPrs
  .filter(pr => pr.mergedAt && pr.author?.login)
  .map(pr => normalizePr(pr, false));

const unmergedRecords = unmergedPrs
  .filter(pr => !pr.mergedAt && pr.author?.login && hasApprovedReview(pr))
  .map(pr => normalizePr(pr, true));

const issueRecords = authoredIssues
  .filter(issue => issue.author?.login && !bountyByNumber.has(String(issue.number)))
  .map(issue => ({
    recordType: 'issue',
    isUnmergedApproved: false,
    contributorGithubUsername: issue.author?.login ?? 'unknown',
    prId: String(issue.number),
    title: issue.title || '',
    body: (issue.body || '').slice(0, 2000),
    month: period.month,
    mergedAt: null,
    createdAt: issue.createdAt,
    additions: 0,
    deletions: 0,
    changedFiles: 0,
    files: [],
    filesStr: '',
    labels: (issue.labels?.nodes ?? []).map(l => l.name).filter(Boolean),
    labelsStr: (issue.labels?.nodes ?? []).map(l => l.name).filter(Boolean).join(', '),
    reviews: [],
    reviewsStr: '',
    linkedIssues: [],
    linkedIssuesStr: '',
    referencedIssueNumbers: [],
    bountyCandidates: [],
    bountyContextStr: ''
  }));

const seenNumbers = new Set();
const allRecords = [];
for (const r of [...mergedRecords, ...unmergedRecords, ...issueRecords]) {
  if (!seenNumbers.has(r.prId)) {
    seenNumbers.add(r.prId);
    allRecords.push(r);
  }
}

allRecords.sort((a, b) => new Date(a.mergedAt || a.createdAt || 0) - new Date(b.mergedAt || b.createdAt || 0));

return [{
  json: {
    month: period.month,
    fromIso: period.fromIso,
    toIso: period.toIso,
    generatedAt: period.generatedAt,
    repoFullName: period.repoFullName,
    profiles: period.profiles,
    records: allRecords
  }
}];

const input = $input.first().json;
const records = input.records ?? [];

function firstMatch(regex, values) {
  for (const value of values) {
    if (!value) continue;
    const match = String(value).match(regex);
    if (match) return match[1] || match[0];
  }
  return '';
}

function sanitizeFeatureKey(value) {
  return String(value || '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^A-Za-z0-9#_-]/g, '')
    .slice(0, 80);
}

const recordsWithFeatureKeys = records.map(record => {
  const explicitKey = firstMatch(/\b([A-Z][A-Z0-9]{0,15}-\d+|WF\d+|PRD[_]\d+)\b/, [
    record.title,
    record.body,
    ...(record.files || [])
  ]);

  const hashRef = firstMatch(/#(\d+)/, [record.title]);

  let featureKey = '';
  let featureKeySource = '';

  if (explicitKey) {
    featureKey = sanitizeFeatureKey(explicitKey);
    featureKeySource = 'explicit';
  } else if (hashRef && !explicitKey) {
    featureKey = `ISSUE-${hashRef}`;
    featureKeySource = 'explicit_hash';
  } else if ((record.linkedIssues || []).length > 0) {
    featureKey = `ISSUE-${record.linkedIssues[0].number}`;
    featureKeySource = 'issue';
  } else {
    featureKey = record.recordType === 'issue' ? `ISSUE-${record.prId}` : `PR-${record.prId}`;
    featureKeySource = 'fallback';
  }

  return {
    ...record,
    featureKey,
    featureKeySource
  };
});

return [{
  json: {
    ...input,
    records: recordsWithFeatureKeys
  }
}];

const input = $input.first().json;
const records = (input.records ?? []).slice().sort((a, b) => new Date(a.mergedAt || a.createdAt || 0) - new Date(b.mergedAt || b.createdAt || 0));

const groups = new Map();

for (const record of records) {
  const key = [record.contributorGithubUsername, record.month, record.featureKey].join('::');

  if (!groups.has(key)) {
    groups.set(key, {
      contributorGithubUsername: record.contributorGithubUsername,
      month: record.month,
      featureKeyCandidate: record.featureKey,
      featureKeySource: record.featureKeySource,
      anchorPrId: record.prId,
      prIds: [],
      titles: [],
      bodies: [],
      recordTypes: [],
      files: new Set(),
      reviews: new Set(),
      linkedIssues: new Map(),
      bountyCandidates: new Map(),
      additionsTotal: 0,
      deletionsTotal: 0,
      changedFilesTotal: 0,
      dateFirst: record.mergedAt || record.createdAt,
      dateLast: record.mergedAt || record.createdAt
    });
  }

  const group = groups.get(key);
  group.prIds.push(record.prId);
  group.titles.push(record.title);
  group.bodies.push((record.body || '').slice(0, 500));
  group.recordTypes.push(record.recordType || 'pull_request');
  for (const file of record.files || []) group.files.add(file);
  for (const review of record.reviews || []) group.reviews.add(review);
  for (const issue of record.linkedIssues || []) group.linkedIssues.set(issue.number, issue);
  for (const bounty of record.bountyCandidates || []) group.bountyCandidates.set(bounty.number, bounty);
  group.additionsTotal += Number(record.additions || 0);
  group.deletionsTotal += Number(record.deletions || 0);
  group.changedFilesTotal += Number(record.changedFiles || 0);
  const recordDate = record.mergedAt || record.createdAt;
  if (recordDate) group.dateLast = recordDate;
}

const serializedGroups = Array.from(groups.values()).map(group => {
  const files = Array.from(group.files);
  const reviews = Array.from(group.reviews);
  const linkedIssues = Array.from(group.linkedIssues.values());
  const bountyCandidates = Array.from(group.bountyCandidates.values());
  const hasIssueRecords = group.recordTypes.includes('issue');

  return {
    contributorGithubUsername: group.contributorGithubUsername,
    month: group.month,
    featureKeyCandidate: group.featureKeyCandidate,
    featureKeySource: group.featureKeySource,
    anchorPrId: group.anchorPrId,
    prIds: group.prIds,
    prIdsStr: group.prIds.join(', '),
    prCount: group.prIds.length,
    titles: group.titles,
    titlesStr: group.titles.join(' | '),
    bodiesStr: group.bodies.filter(Boolean).join('\n---\n').slice(0, 2000),
    recordTypes: [...new Set(group.recordTypes)],
    hasIssueRecords,
    additionsTotal: group.additionsTotal,
    deletionsTotal: group.deletionsTotal,
    changedFilesTotal: group.changedFilesTotal,
    uniqueFilesCount: files.length,
    files,
    filesStr: files.slice(0, 40).join(', '),
    reviews,
    reviewsStr: reviews.join('; '),
    linkedIssues,
    linkedIssuesStr: linkedIssues.map(issue => `#${issue.number} ${issue.title}`).join('; '),
    bountyCandidates,
    bountyContextStr: bountyCandidates.length
      ? bountyCandidates.map(issue => `#${issue.number} ${issue.title}`).join('; ')
      : 'NONE',
    dateFirst: group.dateFirst,
    dateLast: group.dateLast
  };
});

return [{
  json: {
    month: input.month,
    hasCandidates: serializedGroups.length > 0,
    groups: serializedGroups
  }
}];

const groups = $input.first().json.groups ?? [];

// Auto-filtr: oczywiste routine odrzucamy BEZ LLM (oszczednosc tokenow).
// Reszta idzie do AI do oceny.
const ROUTINE_PATTERNS = /^(chore|release|bump|version|changelog|merge branch|update dep|renovate|dependabot)/i;

const forLlm = [];
const autoRoutine = [];

for (const g of groups) {
  const titles = (g.titlesStr || '').toLowerCase();
  const isSmall = g.additionsTotal < 15 && g.changedFilesTotal <= 2;
  const isBump = ROUTINE_PATTERNS.test(g.titlesStr || '');
  const isChangelog = (g.files || []).every(f => /changelog|package.json|yarn.lock|pnpm-lock/i.test(f));

  if (isBump || (isSmall && isChangelog)) {
    autoRoutine.push({ json: { ...g, autoLevel: 'routine' } });
  } else {
    forLlm.push({ json: g });
  }
}

// Auto-routine items przejda bezposrednio do Parse LLM Output jako routine.
// Tylko forLlm idzie do AI.
return forLlm;

const items = $input.all();
const originals = $('Expand Contribution Candidates1').all();

function asObject(candidate) {
  if (!candidate) return null;
  if (typeof candidate === 'object' && !Array.isArray(candidate)) return candidate;
  if (typeof candidate !== 'string') return null;

  const trimmed = candidate.trim();
  if (!trimmed) return null;

  try {
    return JSON.parse(trimmed);
  } catch {}

  const start = trimmed.indexOf('{');
  const end = trimmed.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    try {
      return JSON.parse(trimmed.slice(start, end + 1));
    } catch {}
  }

  return null;
}

function asBoolean(value) {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    return ['true', '1', 'yes'].includes(value.trim().toLowerCase());
  }
  return Boolean(value);
}

return items.map((item, index) => {
  const parsed =
    asObject(item.json.output) ||
    asObject(item.json.text) ||
    asObject(item.json.response) ||
    asObject(item.json.completion) ||
    asObject(item.json);

  if (!parsed || !['L4', 'L3', 'L2', 'L1', 'routine'].includes(parsed?.level)) {
    throw new Error(`LLM returned invalid format for item ${index}. Raw: ${JSON.stringify(item.json).slice(0, 300)}`);
  }

  const orig = originals[index]?.json ?? {};
  const fallbackFeatureKey = orig.featureKeyCandidate || `PR-${orig.anchorPrId || '0'}`;
  const level = parsed.level;
  const featureKey = typeof parsed?.featureKey === 'string' && parsed.featureKey.trim()
    ? parsed.featureKey.trim().slice(0, 80)
    : fallbackFeatureKey;
  const impactBonus = asBoolean(parsed?.impactBonus);
  const bountyApplied = asBoolean(parsed?.bountyApplied);
  const rationale = typeof parsed?.rationale === 'string' ? parsed.rationale.trim().slice(0, 500) : '';

  return {
    json: {
      contributorGithubUsername: orig.contributorGithubUsername || 'unknown',
      prId: orig.anchorPrId || '0',
      month: orig.month || '',
      featureKey,
      level,
      impactBonus,
      bountyApplied,
      rationale
    }
  };
});
